fun max_product(num_str: str, N: int, K: int) -> int:
    if N == 1:
        return 1
    else:
        if K == 0:
            return int(num_str[0])
        else:
            num1 = max_product(num_str[0:N+1], N-1)
            num2 = max_product(num_str[0:N], N)
            return max(num1*int(num_str[N])*num2, num1*int(num_str[N-1])*num2, int(num_str[N-1])*num2)

