def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = ""
    for i in range(n):
        if coeffs[i] != 0:
            prefix = "+" if i == 0 else ""
            suffix = "x" if i == 1 else "x^" + str(i)
            result += prefix + str(coeffs[i]) + suffix
    return result
